+// Helper for 8-bit counting sort pass
+static void counting_sort_byte(uint32_t* input, uint32_t* output, size_t n, int shift) {
+    // 256 buckets for 8-bit radix
+    uint32_t counts[256] = {0};
+
+    // 1. Count frequencies
+    for (size_t i = 0; i < n; ++i) {
+        // Extract the relevant byte
+        uint8_t key = (input[i] >> shift) & 0xFF;
+        counts[key]++;
+    }
+
+    // 2. Compute cumulative counts
+    uint32_t cumulative_counts[256] = {0};
+    uint32_t total = 0;
+    for (int i = 0; i < 256; ++i) {
+        cumulative_counts[i] = total;
+        total += counts[i];
+    }
+
+    // 3. Distribute elements stably
+    // We use a temporary array to store output temporarily if we don't want to overwrite input immediately
+    // However, for LSD Radix, we typically use ping-ponging or a full auxiliary buffer per pass.
+    // Since 'output' is meant to be the destination for this pass, we use it directly.
+    
+    // Reset counts for placement tracking
+    for (int i = 0; i < 256; ++i) {
+        counts[i] = 0;
+    }
+
+    for (size_t i = 0; i < n; ++i) {
+        uint8_t key = (input[i] >> shift) & 0xFF;
+        size_t dest_index = cumulative_counts[key]++;
+        output[dest_index] = input[i];
+    }
 }

